import numpy as np

# Pattern generator helper
# Each pattern has 64 rows, 8 channels.
# Channel layout:
# Ch 0: Lead 1 (Pulse 25% / Saw)
# Ch 1: Lead 2 / Harmony / Counterpoint (Pulse 12.5% / Bell)
# Ch 2: Fast Arpeggio (Arp Pluck / Pulse)
# Ch 3: Chords / Pad (Warm Pad / Pulse 50%)
# Ch 4: Bassline (Punchy Bass / Saw Bass)
# Ch 5: Kick Drum (Punch Kick)
# Ch 6: Snare Drum / Claps (Crisp Snare / Crash)
# Ch 7: Hi-Hats / Cymbals (Closed Hat / Open Hat)

def empty_cell():
    return {'note': 0, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}

def make_empty_pattern(rows=64, channels=8):
    return [[empty_cell() for _ in range(channels)] for _ in range(rows)]

# Standard drum helper
def add_drum_beat(pattern, kick_rows, snare_rows, hat_rows, open_hat_rows=[], fill_rows=[]):
    # Ch 5: Kick
    for r in kick_rows:
        pattern[r][5] = {'note': 'C-4', 'instrument': 9, 'volume': 64, 'effect': 0, 'effect_param': 0}
    # Ch 6: Snare
    for r in snare_rows:
        pattern[r][6] = {'note': 'C-4', 'instrument': 10, 'volume': 60, 'effect': 0, 'effect_param': 0}
    # Ch 7: Closed Hats
    for r in hat_rows:
        pattern[r][7] = {'note': 'C-4', 'instrument': 11, 'volume': 48, 'effect': 0, 'effect_param': 0}
    # Ch 7: Open Hats
    for r in open_hat_rows:
        pattern[r][7] = {'note': 'C-4', 'instrument': 12, 'volume': 54, 'effect': 0, 'effect_param': 0}
    # Ch 6: Fill crash/noise
    for r, v in fill_rows:
        pattern[r][6] = {'note': 'C-4', 'instrument': 14, 'volume': v, 'effect': 0, 'effect_param': 0}

print('Pattern builder helpers defined.')
