import json, base64, wave, subprocess, os
import numpy as np

def build_full_tune():
    sr = 44100
    f_C4 = 261.625565

    # 1. Synthesize Instrument Samples
    instruments = {}
    N = 256
    t = np.linspace(0, 1, N, endpoint=False)

    # Inst 1: Pulse 12.5%
    sq12 = np.where(t < 0.125, 0.9, -0.9)
    sq12 = np.convolve(sq12, np.ones(3)/3, mode='same')
    instruments[1] = {
        'name': 'Pulse 12.5%',
        'pcm': (sq12 / np.max(np.abs(sq12)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': N, 'flags': 1,
        'rel_note': 36, 'finetune': 2, 'volume': 54
    }

    # Inst 2: Pulse 25%
    sq25 = np.where(t < 0.25, 0.9, -0.9)
    sq25 = np.convolve(sq25, np.ones(3)/3, mode='same')
    instruments[2] = {
        'name': 'Pulse 25%',
        'pcm': (sq25 / np.max(np.abs(sq25)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': N, 'flags': 1,
        'rel_note': 36, 'finetune': 2, 'volume': 58
    }

    # Inst 3: Square 50%
    sq50 = np.where(t < 0.50, 0.9, -0.9)
    sq50 = np.convolve(sq50, np.ones(3)/3, mode='same')
    instruments[3] = {
        'name': 'Square 50%',
        'pcm': (sq50 / np.max(np.abs(sq50)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': N, 'flags': 1,
        'rel_note': 36, 'finetune': 2, 'volume': 56
    }

    # Inst 4: Saw Lead
    saw = 2.0 * (t - 0.5)
    saw = np.convolve(saw, np.ones(3)/3, mode='same')
    instruments[4] = {
        'name': 'Saw Lead',
        'pcm': (saw / np.max(np.abs(saw)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': N, 'flags': 1,
        'rel_note': 36, 'finetune': 2, 'volume': 56
    }

    # Inst 5: Triangle
    tri = 2.0 * np.abs(2.0 * (t - np.floor(t + 0.5))) - 1.0
    instruments[5] = {
        'name': 'Triangle Lead',
        'pcm': (tri / np.max(np.abs(tri)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': N, 'flags': 1,
        'rel_note': 36, 'finetune': 2, 'volume': 64
    }

    # Inst 6: Bell Pluck
    dur_bell = 0.35
    L_bell = int(sr * dur_bell)
    tp = np.linspace(0, dur_bell, L_bell, endpoint=False)
    pluck = (np.sin(2*np.pi*f_C4*tp) * np.exp(-12*tp) +
             0.5 * np.sin(2*np.pi*2*f_C4*tp) * np.exp(-18*tp) +
             0.35 * np.sin(2*np.pi*3*f_C4*tp) * np.exp(-24*tp) +
             0.25 * np.sin(2*np.pi*4*f_C4*tp) * np.exp(-32*tp))
    instruments[6] = {
        'name': 'Chiptune Bell',
        'pcm': (pluck / np.max(np.abs(pluck)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 60
    }

    # Inst 7: Punchy Bass
    dur_b = 0.45
    L_b = int(sr * dur_b)
    tb = np.linspace(0, dur_b, L_b, endpoint=False)
    p_env = np.exp(-60 * tb) * 1.5 + 1.0
    phase_b = 2 * np.pi * f_C4 * np.cumsum(p_env) / sr
    bass = np.sign(np.sin(phase_b)) * 0.6 + 0.4 * np.sin(phase_b)
    for _ in range(2):
        bass = np.convolve(bass, np.ones(5)/5, mode='same')
    bass = bass * np.exp(-7 * tb)
    instruments[7] = {
        'name': 'Punchy Bass',
        'pcm': (bass / np.max(np.abs(bass)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 64
    }

    # Inst 8: Arp Pluck
    dur_a = 0.18
    L_a = int(sr * dur_a)
    ta = np.linspace(0, dur_a, L_a, endpoint=False)
    arp_pluck = (np.sin(2*np.pi*f_C4*ta) + 0.5 * np.sin(2*np.pi*2*f_C4*ta) + 0.3 * np.sin(2*np.pi*4*f_C4*ta)) * np.exp(-22 * ta)
    instruments[8] = {
        'name': 'Arp Pluck',
        'pcm': (arp_pluck / np.max(np.abs(arp_pluck)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 62
    }

    # Inst 9: Punch Kick
    dur_k = 0.22
    L_k = int(sr * dur_k)
    tk = np.linspace(0, dur_k, L_k, endpoint=False)
    fk = 45 + 180 * np.exp(-60 * tk)
    phase_k = 2 * np.pi * np.cumsum(fk) / sr
    kick = np.sin(phase_k) + 0.2 * np.sin(2 * phase_k)
    click = np.random.uniform(-1, 1, L_k) * np.exp(-250 * tk) * 0.35
    kick = (kick + click) * np.exp(-14 * tk)
    kick = np.clip(kick * 1.25, -1.0, 1.0)
    instruments[9] = {
        'name': 'Punch Kick',
        'pcm': (kick / np.max(np.abs(kick)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 64
    }

    # Inst 10: Crisp Snare
    dur_s = 0.20
    L_s = int(sr * dur_s)
    ts = np.linspace(0, dur_s, L_s, endpoint=False)
    tone_s = np.sin(2 * np.pi * (190 * np.exp(-45 * ts) + 125) * ts) * np.exp(-28 * ts)
    noise_s = np.random.uniform(-1, 1, L_s) * np.exp(-18 * ts)
    noise_s = noise_s - np.convolve(noise_s, np.ones(7)/7, mode='same')
    snare = (tone_s * 0.45 + noise_s * 0.85)
    instruments[10] = {
        'name': 'Crisp Snare',
        'pcm': (snare / np.max(np.abs(snare)) * 32000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 60
    }

    # Inst 11: Closed Hat
    dur_h = 0.05
    L_h = int(sr * dur_h)
    th = np.linspace(0, dur_h, L_h, endpoint=False)
    noise_h = np.random.uniform(-1, 1, L_h)
    noise_h = noise_h - np.convolve(noise_h, np.ones(5)/5, mode='same')
    hat_c = noise_h * np.exp(-75 * th)
    instruments[11] = {
        'name': 'Closed Hat',
        'pcm': (hat_c / np.max(np.abs(hat_c)) * 26000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 48
    }

    # Inst 12: Open Hat
    dur_oh = 0.22
    L_oh = int(sr * dur_oh)
    toh = np.linspace(0, dur_oh, L_oh, endpoint=False)
    noise_oh = np.random.uniform(-1, 1, L_oh)
    noise_oh = noise_oh - np.convolve(noise_oh, np.ones(5)/5, mode='same')
    hat_o = noise_oh * np.exp(-18 * toh)
    instruments[12] = {
        'name': 'Open Hat',
        'pcm': (hat_o / np.max(np.abs(hat_o)) * 26000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 46
    }

    # Inst 13: Warm Pad
    dur_p = 0.4
    L_p = int(sr * dur_p)
    tp = np.linspace(0, dur_p, L_p, endpoint=False)
    pad = (np.sin(2*np.pi*f_C4*tp) + 
           0.5 * np.sin(2*np.pi*2*f_C4*tp) + 
           0.3 * np.sin(2*np.pi*3*f_C4*tp) +
           0.35 * np.sin(2*np.pi*(f_C4*1.004)*tp) +
           0.35 * np.sin(2*np.pi*(f_C4*0.996)*tp))
    fade_len = int(sr * 0.02)
    pad[:fade_len] = pad[:fade_len] * np.linspace(0, 1, fade_len) + pad[-fade_len:] * np.linspace(1, 0, fade_len)
    instruments[13] = {
        'name': 'Warm Pad',
        'pcm': (pad / np.max(np.abs(pad)) * 30000).astype(np.int16),
        'loop_start': 0, 'loop_len': L_p, 'flags': 1,
        'rel_note': 41, 'finetune': -24, 'volume': 48
    }

    # Inst 14: Crash Noise
    dur_e = 0.35
    L_e = int(sr * dur_e)
    te = np.linspace(0, dur_e, L_e, endpoint=False)
    noise_e = np.random.uniform(-1, 1, L_e)
    fill = noise_e * np.exp(-12 * te)
    instruments[14] = {
        'name': 'Crash Noise',
        'pcm': (fill / np.max(np.abs(fill)) * 28000).astype(np.int16),
        'loop_start': 0, 'loop_len': 0, 'flags': 0,
        'rel_note': 41, 'finetune': -24, 'volume': 52
    }

    # Helpers for patterns
    def empty_pat():
        return [[{'note': 0, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0} for _ in range(8)] for _ in range(64)]

    # Standard Basslines
    # Bass A (Dm -> Bb -> C -> Am)
    def set_bass_A(p, inst=7, octv=2):
        # Bar 1 (0-15): D
        # Bar 2 (16-31): Bb
        # Bar 3 (32-47): C
        # Bar 4 (48-63): A
        roots = [(0, f'D-{octv}'), (16, f'A#{octv-1}'), (32, f'C-{octv}'), (48, f'A-{octv-1}')]
        for start_r, note_name in roots:
            # 16th note groovy pattern: hits on 0, 3, 6, 8, 10, 12, 14
            hits = [0, 3, 6, 8, 10, 12, 14]
            for h in hits:
                r = start_r + h
                # Octave jump on some offbeats
                n = note_name
                if h in [6, 14]:
                    # octave up
                    base_pitch = note_name[:2]
                    base_oct = int(note_name[2])
                    n = f'{base_pitch}{base_oct+1}'
                p[r][4] = {'note': n, 'instrument': inst, 'volume': 64, 'effect': 0, 'effect_param': 0}

    # Bass B (Gm -> C -> F -> A7)
    def set_bass_B(p, inst=7, octv=2):
        roots = [(0, f'G-{octv-1}'), (16, f'C-{octv}'), (32, f'F-{octv-1}'), (48, f'A-{octv-1}')]
        for start_r, note_name in roots:
            hits = [0, 3, 6, 8, 10, 12, 14]
            for h in hits:
                r = start_r + h
                n = note_name
                if h in [6, 14]:
                    base_pitch = note_name[:2]
                    base_oct = int(note_name[2])
                    n = f'{base_pitch}{base_oct+1}'
                p[r][4] = {'note': n, 'instrument': inst, 'volume': 64, 'effect': 0, 'effect_param': 0}

    # Bass C (Bb -> C -> Dm -> A7)
    def set_bass_C(p, inst=7, octv=2):
        roots = [(0, f'A#{octv-1}'), (16, f'C-{octv}'), (32, f'D-{octv}'), (48, f'A-{octv-1}')]
        for start_r, note_name in roots:
            hits = [0, 2, 4, 6, 8, 10, 12, 14]
            for h in hits:
                r = start_r + h
                n = note_name
                if h in [4, 12]:
                    base_pitch = note_name[:2]
                    base_oct = int(note_name[2])
                    n = f'{base_pitch}{base_oct+1}'
                p[r][4] = {'note': n, 'instrument': inst, 'volume': 64, 'effect': 0, 'effect_param': 0}

    # Standard Arpeggios (16th notes on Ch 2)
    # Arp A: Dm -> Bb -> C -> Am
    def set_arp_A(p, inst=8):
        # Dm: D-4, F-4, A-4, D-5
        arp_dm = ['D-4', 'F-4', 'A-4', 'D-5', 'F-5', 'D-5', 'A-4', 'F-4']
        # Bb: Bb3, D-4, F-4, Bb4, D-5, Bb4, F-4, D-4
        arp_bb = ['A#3', 'D-4', 'F-4', 'A#4', 'D-5', 'A#4', 'F-4', 'D-4']
        # C: C-4, E-4, G-4, C-5, E-5, C-5, G-4, E-4
        arp_c  = ['C-4', 'E-4', 'G-4', 'C-5', 'E-5', 'C-5', 'G-4', 'E-4']
        # Am: A-3, C-4, E-4, A-4, C-5, A-4, E-4, C-4
        arp_am = ['A-3', 'C-4', 'E-4', 'A-4', 'C-5', 'A-4', 'E-4', 'C-4']

        progressions = [(0, arp_dm), (16, arp_bb), (32, arp_c), (48, arp_am)]
        for start_r, seq in progressions:
            for i in range(16):
                note = seq[i % len(seq)]
                vol = 52 if (i % 2 == 0) else 42
                p[start_r + i][2] = {'note': note, 'instrument': inst, 'volume': vol, 'effect': 0, 'effect_param': 0}

    # Arp B: Gm -> C -> F -> A7
    def set_arp_B(p, inst=8):
        arp_gm = ['G-3', 'A#3', 'D-4', 'G-4', 'A#4', 'G-4', 'D-4', 'A#3']
        arp_c7 = ['C-4', 'E-4', 'G-4', 'A#4', 'C-5', 'A#4', 'G-4', 'E-4']
        arp_f  = ['F-3', 'A-3', 'C-4', 'F-4', 'A-4', 'F-4', 'C-4', 'A-3']
        arp_a7 = ['A-3', 'C#4', 'E-4', 'G-4', 'A-4', 'G-4', 'E-4', 'C#4']

        progressions = [(0, arp_gm), (16, arp_c7), (32, arp_f), (48, arp_a7)]
        for start_r, seq in progressions:
            for i in range(16):
                note = seq[i % len(seq)]
                vol = 52 if (i % 2 == 0) else 42
                p[start_r + i][2] = {'note': note, 'instrument': inst, 'volume': vol, 'effect': 0, 'effect_param': 0}

    # Arp C: Bb -> C -> Dm -> A7
    def set_arp_C(p, inst=8):
        arp_bb = ['A#3', 'D-4', 'F-4', 'A#4', 'D-5', 'A#4', 'F-4', 'D-4']
        arp_c  = ['C-4', 'E-4', 'G-4', 'C-5', 'E-5', 'C-5', 'G-4', 'E-4']
        arp_dm = ['D-4', 'F-4', 'A-4', 'D-5', 'F-5', 'D-5', 'A-4', 'F-4']
        arp_a7 = ['A-3', 'C#4', 'E-4', 'G-4', 'A-4', 'G-4', 'E-4', 'C#4']

        progressions = [(0, arp_bb), (16, arp_c), (32, arp_dm), (48, arp_a7)]
        for start_r, seq in progressions:
            for i in range(16):
                note = seq[i % len(seq)]
                vol = 54 if (i % 2 == 0) else 44
                p[start_r + i][2] = {'note': note, 'instrument': inst, 'volume': vol, 'effect': 0, 'effect_param': 0}

    # Standard Pads / Chords on Ch 3
    def set_pad_A(p, inst=13):
        # Dm (D-4, F-4, A-4)
        p[0][3] = {'note': 'D-4', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[15][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}
        # Bb (Bb3, D-4, F-4)
        p[16][3] = {'note': 'A#3', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[31][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}
        # C (C-4, E-4, G-4)
        p[32][3] = {'note': 'C-4', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[47][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}
        # Am (A-3, C-4, E-4)
        p[48][3] = {'note': 'A-3', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[63][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}

    def set_pad_B(p, inst=13):
        p[0][3] = {'note': 'G-3', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[15][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}
        p[16][3] = {'note': 'C-4', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[31][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}
        p[32][3] = {'note': 'F-3', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[47][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}
        p[48][3] = {'note': 'A-3', 'instrument': inst, 'volume': 46, 'effect': 0, 'effect_param': 0}
        p[63][3] = {'note': 97, 'instrument': 0, 'volume': 0, 'effect': 0, 'effect_param': 0}

    # Drums
    def set_drums_full(p, fill_at_end=True):
        # 4-on-the-floor kicks on 0, 4, 8, 12, ... 60
        kicks = [i*4 for i in range(16)]
        # Snares on 4, 12, 20, 28, 36, 44, 52, 60
        snares = [4 + i*8 for i in range(8)]
        # Closed hats on 2, 6, 10, 14, 18 ...
        hats = [i*2 for i in range(32) if i*2 not in [2, 10, 18, 26, 34, 42, 50, 58]]
        # Open hats on offbeats 2, 10, 18, 26, 34, 42, 50, 58
