            'instrument': inst_id,
            'name': inst['name']
        }})
        b64 = base64.b64encode(inst['pcm'].tobytes()).decode('ascii')
        batch.append({'name': 'sample_create_from_pcm', 'arguments': {
            'instrument': inst_id,
            'sample': 0,
            'pcm': b64,
            'encoding': 'int16',
            'name': inst['name']
        }})
        batch.append({'name': 'sample_set', 'arguments': {
            'instrument': inst_id,
            'sample': 0,
            'relative_note': inst['rel_note'],
            'finetune': inst['finetune'],
            'loop_start': inst['loop_start'],
            'loop_length': inst['loop_len'],
            'flags': inst['flags'],
            'volume': inst['volume']
        }})

    # 3. Add pattern cells
    for pat_id, pat_data in patterns.items():
        for r in range(64):
            for ch in range(8):
                cell = pat_data[r][ch]
                if cell['note'] != 0 or cell['instrument'] != 0 or cell['volume'] != 0 or cell['effect'] != 0:
                    args = {
                        'pattern': pat_id,
                        'row': r,
                        'channel': ch,
                    }
                    if cell['note'] != 0:
                        args['note'] = cell['note']
                    if cell['instrument'] != 0:
                        args['instrument'] = cell['instrument']
                    if cell['volume'] != 0:
                        args['volume'] = cell['volume']
                    if cell['effect'] != 0:
                        args['effect'] = cell['effect']
                    if cell['effect_param'] != 0:
                        args['effect_param'] = cell['effect_param']
                    batch.append({'name': 'pattern_set_cell', 'arguments': args})

    # 4. Set order list
    for pos, pat_idx in enumerate(order):
        batch.append({'name': 'order_set', 'arguments': {
            'position': pos,
            'pattern': pat_idx
        }})

    # Save to JSON and run batch
    print(f'Total batch operations: {len(batch)}')
    with open('batch_build.json', 'w') as f:
        json.dump(batch, f)

