        (48, 'F-6', 0, 0), (52, 'E-6', 0, 0), (56, 'D-6', 0, 0), (58, 'C-6', 0, 0), (60, 'A-5', 0, 0), (62, 'C-6', 0, 0)
    ]
    for r, n, eff, prm in lead_out:
        p7[r][0] = {'note': n, 'instrument': 4, 'volume': 64, 'effect': eff, 'effect_param': prm}
    add_echo(p7, 0, 1, delay=3, echo_vol_scale=0.65)
    patterns[7] = p7

    order = [0, 1, 2, 3, 4, 5, 6, 7]
    return instruments, patterns, order, CHANNELS

def main():
    instruments, patterns, order, channels = build_module()

    batch = []
    batch.append({'name': 'module_new', 'arguments': {'channels': channels, 'name': 'Cyber Horizon'}})
    batch.append({'name': 'song_set', 'arguments': {
        'bpm': 138,
        'speed': 4,
        'length': len(order),
        'loop_start': 0
    }})

    # Add instruments & samples
    for inst_id, inst in instruments.items():
        batch.append({'name': 'instrument_set', 'arguments': {
            'instrument': inst_id,
            'name': inst['name']
        }})
        b64 = base64.b64encode(inst['pcm'].tobytes()).decode('ascii')
        batch.append({'name': 'sample_create_from_pcm', 'arguments': {
            'instrument': inst_id,
            'sample': 0,
            'pcm': b64,
            'encoding': 'int16',
            'name': inst['name']
        }})
        batch.append({'name': 'sample_set', 'arguments': {
            'instrument': inst_id,
            'sample': 0,
            'relative_note': inst['rel_note'],
            'finetune': inst['finetune'],
            'loop_start': inst['loop_start'],
            'loop_length': inst['loop_len'],
            'flags': inst['flags'],
            'volume': inst['volume']
        }})

    # Add pattern cells
    for pat_id, pat_data in patterns.items():
        for r in range(64):
            for ch in range(channels):
                cell = pat_data[r][ch]
                if cell['note'] != 0 or cell['instrument'] != 0 or cell['volume'] != 0 or cell['effect'] != 0:
                    args = {
                        'pattern': pat_id,
                        'row': r,
                        'channel': ch,
                    }
                    if cell['note'] != 0:
                        args['note'] = cell['note']
                    if cell['instrument'] != 0:
                        args['instrument'] = cell['instrument']
                    if cell['volume'] != 0:
                        args['volume'] = cell['volume']
                    if cell['effect'] != 0:
                        args['effect'] = cell['effect']
                    if cell['effect_param'] != 0:
                        args['effect_param'] = cell['effect_param']
                    batch.append({'name': 'pattern_set_cell', 'arguments': args})

    # Set order
    for pos, pat_idx in enumerate(order):
        batch.append({'name': 'order_set', 'arguments': {
            'position': pos,
            'pattern': pat_idx
        }})

    print(f'Total batch operations: {len(batch)}')
    with open('batch_masterpiece.json', 'w') as f:
        json.dump(batch, f)

    print('Executing batch commands...')
    res = subprocess.run(['ft2', 'batch', 'batch_masterpiece.json'], capture_output=True, text=True)
    if res.returncode != 0:
        print('Batch failed:', res.stderr)
        return
    else:
        print('Batch executed successfully!')

    # Save final XM module
    os.makedirs('/workspace/submission', exist_ok=True)
    save_cmd = ['ft2', 'call', 'module_save', json.dumps({'path': '/workspace/submission/tune.xm', 'format': 'xm'})]
    subprocess.run(save_cmd, check=True)
    print('Module saved to /workspace/submission/tune.xm')

    # Render module preview
    render_cmd = ['ft2', 'call', 'module_render', json.dumps({
        'path': '/workspace/submission/tune_preview.wav',
        'loops': 1
    })]
    res_render = subprocess.run(render_cmd, capture_output=True, text=True)
    print('Render result:', res_render.stdout)

if __name__ == '__main__':
    main()
